 return Object.freeze({snapshotId,requestSequence:input.requestSequence,latestFinalizedSequence,currentScriptSection:step.section,currentScriptStepId:step.id,currentScriptStepStatus:status,stepStartedAtSequence:input.stepStartedAtSequence,deliverySequence,responseSequence,lifecycleState,resumeScriptSection:input.resumeScriptSection,resumeScriptStepId:input.resumeScriptStepId,activeAdaptiveRoute:input.activeAdaptiveRoute});
