export function scriptContextFromSnapshot(snapshot:ScriptedConversationSnapshot):ScriptNavigationContext{return {currentScriptSection:snapshot.currentScriptSection,currentScriptStepId:snapshot.currentScriptStepId,currentScriptStepStatus:snapshot.currentScriptStepStatus,resumeScriptSection:snapshot.resumeScriptSection,resumeScriptStepId:snapshot.resumeScriptStepId,activeAdaptiveRoute:snapshot.activeAdaptiveRoute,lifecycleState:snapshot.lifecycleState,deliverySequence:snapshot.deliverySequence,responseSequence:snapshot.responseSequence,snapshotId:snapshot.snapshotId,latestFinalizedSequence:snapshot.latestFinalizedSequence,stepStartedAtSequence:snapshot.stepStartedAtSequence};}
/** Server-side reconstruction proves that the client snapshot matches the exact playbook and finalized rows. */
