 const data={salesMode:input.mode,recordedContext:input.facts,neutralTranscript:input.segments.filter(s=>!s.gap),previousSuggestions:input.history,conversationState:input.conversationState,guardrailState:input.opportunity,scriptNavigation:input.mode==='scripted'?{currentScriptSection:input.currentScriptSection||input.playbook?.scriptSteps[0]?.section||'opening',currentScriptStepId:currentStep?.id||null,currentApprovedStep:currentStep,nextSequentialApprovedStep:nextStep,activeAdaptiveRoute:input.activeAdaptiveRoute===true,resumeLocation:input.resumeScriptStepId?{section:input.resumeScriptSection,stepId:input.resumeScriptStepId}:null}:null,scriptNavigationTargets:input.mode==='scripted'?scriptNavigationTargetOptions(input.playbook,scriptContext):null,approvedWordingIdOptions:input.mode==='scripted'&&input.playbook?[...input.playbook.scriptSteps.map(step=>step.id),...input.playbook.objectionBranches.map(branch=>branch.id),...input.playbook.approvedClaims.map((_,index)=>approvedClaimId(index))]:[],approvedPlaybook:input.mode==='scripted'&&input.playbook?salesPlaybookSummary(input.playbook):null};
